"""Debt payoff planner: avalanche vs snowball simulation."""

from dataclasses import dataclass, replace
from typing import List


class InsufficientBudgetError(ValueError):
    """Raised when the monthly budget cannot cover all minimum payments."""


@dataclass
class Debt:
    name: str
    balance: float
    apr: float
    min_payment: float

    def rounded(self) -> "Debt":
        return Debt(self.name, round(self.balance, 2), self.apr, self.min_payment)


@dataclass
class PayoffResult:
    strategy: str
    months: int
    total_interest: float
    balance_history: List[List[float]]  # snapshot of balances at end of each month


def _priority(debt: Debt, strategy: str):
    if strategy == "avalanche":
        return (-debt.apr, debt.balance)
    elif strategy == "snowball":
        return (debt.balance, -debt.apr)
    raise ValueError(f"unknown strategy: {strategy!r}")


def simulate(debts: List[Debt], budget: float, strategy: str,
             max_months: int = 1200) -> PayoffResult:
    """Simulate monthly payoff until all balances reach zero.

    Each month: accrue interest (balance * apr / 12, rounded to cents),
    pay minimums (capped at balance), then apply leftover budget to debts
    in strategy priority order (also capped so balances never go negative).
    """
    required_minimums = sum(d.min_payment for d in debts)
    if budget < required_minimums:
        raise InsufficientBudgetError(
            f"budget {budget:.2f} is below sum of minimum payments "
            f"{required_minimums:.2f}"
        )

    working = [d.rounded() for d in debts]
    order = sorted(range(len(working)), key=lambda i: _priority(working[i], strategy))

    total_interest = 0.0
    history: List[List[float]] = []

    for month in range(1, max_months + 1):
        if all(d.balance <= 0 for d in working):
            break

        # 1) Monthly interest accrual, rounded to cents.
        for d in working:
            if d.balance > 0:
                interest = round(d.balance * d.apr / 12, 2)
                d.balance = round(d.balance + interest, 2)
                total_interest = round(total_interest + interest, 2)

        # 2) Minimum payments (capped at balance and remaining budget).
        available = budget
        for d in working:
            if d.balance > 0 and available > 0:
                pay = min(d.min_payment, d.balance, available)
                d.balance = round(d.balance - pay, 2)
                available = round(available - pay, 2)

        # 3) Extra money to strategy targets, cascading down the priority
        #    list, always capped at the remaining balance.
        for i in order:
            d = working[i]
            if d.balance > 0 and available > 0:
                pay = min(available, d.balance)
                d.balance = round(d.balance - pay, 2)
                available = round(available - pay, 2)

        history.append([d.balance for d in working])

        if all(d.balance <= 0 for d in working):
            return PayoffResult(strategy, month, total_interest, history)
    else:
        raise RuntimeError(
            f"did not converge within {max_months} months; "
            "budget may only cover interest"
        )

    return PayoffResult(strategy, len(history), total_interest, history)


DEBTS = [
    Debt("card", 5000.0, 0.24, 100.0),
    Debt("car", 12000.0, 0.07, 250.0),
    Debt("loan", 3000.0, 0.12, 60.0),
]
BUDGET = 700.0


# ---------------------------- tests ----------------------------

def test_both_strategies_reach_zero():
    for strategy in ("avalanche", "snowball"):
        result = simulate(DEBTS, BUDGET, strategy)
        assert all(b == 0 for b in result.balance_history[-1]), (
            f"{strategy} final balances not zero: {result.balance_history[-1]}"
        )


def test_avalanche_interest_le_snowball():
    av = simulate(DEBTS, BUDGET, "avalanche")
    sn = simulate(DEBTS, BUDGET, "snowball")
    assert av.total_interest <= sn.total_interest, (
        f"avalanche {av.total_interest} > snowball {sn.total_interest}"
    )


def test_no_negative_balances_payments_capped():
    for strategy in ("avalanche", "snowball"):
        result = simulate(DEBTS, BUDGET, strategy)
        for month, balances in enumerate(result.balance_history, start=1):
            assert all(b >= 0 for b in balances), (
                f"{strategy} month {month} has negative balance: {balances}"
            )


def test_months_to_freedom_reported():
    for strategy in ("avalanche", "snowball"):
        result = simulate(DEBTS, BUDGET, strategy)
        assert isinstance(result.months, int) and result.months > 0


def test_budget_below_sum_of_minimums_raises():
    try:
        simulate(DEBTS, 400.0, "avalanche")  # minimums sum to 410
    except InsufficientBudgetError:
        pass
    else:
        raise AssertionError("expected InsufficientBudgetError")


# ---------------------------- main ----------------------------

if __name__ == "__main__":
    results = [simulate(DEBTS, BUDGET, s) for s in ("avalanche", "snowball")]

    print(f"{'Strategy':<12} {'Months':>7} {'Total Interest':>16}")
    print("-" * 37)
    for r in results:
        print(f"{r.strategy:<12} {r.months:>7} {r.total_interest:>14,.2f}")
    diff = results[1].total_interest - results[0].total_interest
    faster = min(results, key=lambda r: r.months)
    print("-" * 37)
    print(f"Avalanche saves {diff:,.2f} in interest;"
          f" fastest payoff: {faster.strategy} ({faster.months} months)")

